from math import gcd


M = 26
GROUP_SIZE = 5
ORD_A = ord("a")


def _ensure_coprime(a):
    if gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _mod_inverse(a):
    for candidate in range(1, M):
        if (a * candidate) % M == 1:
            return candidate

    # This is unreachable after _ensure_coprime, but keeps the helper safe
    # if it is used independently.
    raise ValueError("a and m must be coprime.")


def _is_letter(ch):
    return len(ch) == 1 and "a" <= ch <= "z"


def _is_digit(ch):
    return len(ch) == 1 and "0" <= ch <= "9"


def _letter_index(ch):
    return ord(ch) - ORD_A


def _index_letter(index):
    return chr(ORD_A + index)


def _group(text):
    return " ".join(
        text[index : index + GROUP_SIZE]
        for index in range(0, len(text), GROUP_SIZE)
    )


def encode(plain_text, a, b):
    _ensure_coprime(a)

    encrypted = []
    for ch in plain_text:
        lowered = ch.lower()
        if ch.isascii() and _is_letter(lowered):
            index = _letter_index(lowered)
            encrypted.append(_index_letter((a * index + b) % M))
        elif ch.isascii() and _is_digit(lowered):
            encrypted.append(lowered)

    return _group("".join(encrypted))


def decode(ciphered_text, a, b):
    _ensure_coprime(a)
    inverse = _mod_inverse(a)

    decrypted = []
    for ch in ciphered_text:
        lowered = ch.lower()
